using System;using System.Net;using System.Text;using System.Collections.Generic;using OpenMetaverse;using OpenMetaverse.StructuredData;using OpenSim.Framework;
public class ClientContext {
 public OSDMap command;public ClientReference owner;public AgentCircuitManager manager=new();public AgentCircuitData input;public ScenePresence actor;public string trace="",region="Region";public int gets,sleeps,logouts,closes;public bool mutated;
 public bool F(string k,bool d=false)=>command.ContainsKey(k)?command[k].AsBoolean():d;public int N(string k,int d=0)=>command.ContainsKey(k)?command[k].AsInteger():d;public string T(string k,string d="")=>command.ContainsKey(k)?command[k].AsString():d;
 public void Log(string op,string detail=""){trace+=op+":"+ClientReference.Hex(detail)+";";if(T("failure")==op)throw new Exception(op);if(!mutated&&T("mutation_op")==op){mutated=true;switch(T("mutation")){case "drop":manager.RemoveCircuit(ClientReference.Id(1));break;case "replace":manager.AddNewCircuit(999,new AgentCircuitData{AgentID=ClientReference.Id(1),circuitcode=999});break;case "replace_input":case "detach":if(T("mutation")=="detach")manager.RemoveCircuit(ClientReference.Id(1));input=new AgentCircuitData{AgentID=ClientReference.Id(9),circuitcode=999,firstname="Replacement"};break;case "rename":input.firstname="Changed";region="Changed Region";break;case "actor_id":if(actor!=null)actor.agent=ClientReference.Id(9);break;case "drop_actor":actor=null;break;case "null_handler":owner.m_authenticateHandler=null;break;}}}
}
public class VerificationLog {ClientContext c;public VerificationLog(ClientContext ctx){c=ctx;}public void DebugFormat(string f,params object[] args){if(f.StartsWith("[SCENE]: Exception while closing aborted client:"))c.Log("cleanup-error");else c.Log("debug",string.Format(f,args));}public void WarnFormat(string f,params object[] args)=>c.Log("warn",string.Format(f,args));}
public class CircuitFacade {ClientContext c;public CircuitFacade(ClientContext ctx){c=ctx;}public AgentCircuitData GetAgentCircuitData(UUID a){c.Log("get",a.ToString());return c.manager.GetAgentCircuitData(a);}public void RemoveCircuit(UUID a){c.Log("remove",a.ToString());c.manager.RemoveCircuit(a);}}
public class UserVerifier:IUserAgentVerificationModule {ClientContext c;public UserVerifier(ClientContext ctx){c=ctx;}public bool VerifyClient(AgentCircuitData data,string address){c.Log("verify",(ReferenceEquals(data,c.input)?"1:":"0:")+address);return c.F("verified",true);}}
public class ClientSession {ClientContext c;public ClientSession(ClientContext ctx){c=ctx;}public UUID SessionId{get{c.Log("session");return ClientReference.Id(3);}}}
public class ScenePresence {ClientContext c;public UUID agent=ClientReference.Id(1);ClientSession client;public ScenePresence(ClientContext ctx){c=ctx;client=new(ctx);}public ClientSession ControllingClient{get{c.Log("client");return c.F("client",true)?client:null;}}public UUID UUID{get{c.Log("agent-id");return agent;}}}
public class ClientPresenceService {ClientContext c;public ClientPresenceService(ClientContext ctx){c=ctx;}public bool LogoutAgent(UUID session){c.Log("logout",session.ToString());++c.logouts;return c.F("logout_result",true);}}
public class VerificationRegion {ClientContext c;public VerificationRegion(ClientContext ctx){c=ctx;}public string RegionName{get{c.Log("region");return c.region;}}}
public class ClientReferenceBase {public virtual bool CheckClient(UUID agent,IPEndPoint ep)=>false;}
public partial class ClientReference:ClientReferenceBase {
 public ClientContext ctx;public CircuitFacade m_authenticateHandler;public VerificationRegion RegionInfo;public VerificationLog m_log;UserVerifier verifier;ClientPresenceService service;
 public ClientReference(ClientContext c){ctx=c;c.owner=this;m_authenticateHandler=c.F("null_handler")?null:new(c);RegionInfo=c.F("null_region")?null:new(c);m_log=new(c);verifier=new(c);service=new(c);}
 public T RequestModuleInterface<T>()where T:class{ctx.Log("module");return ctx.F("module",true)?verifier as T:null;}
 public ScenePresence GetScenePresence(UUID agent){ctx.Log("presence",agent.ToString());++ctx.gets;return ctx.F("presence",true)&&ctx.gets>=ctx.N("after",1)?ctx.actor:null;}
 public ClientPresenceService PresenceService{get{ctx.Log("presence-service");return ctx.F("service",true)?service:null;}}
 public bool CloseAgent(UUID agent,bool force){ctx.Log("close",agent+":"+(force?"1":"0"));++ctx.closes;return ctx.F("close_result",true);}
 public void Sleep(int ms){ctx.Log("sleep",ms.ToString());++ctx.sleeps;}
 public bool Verify(AgentCircuitData data,IPEndPoint ep,out bool via)=>VerifyClient(data,ep,out via);public ScenePresence Wait(UUID agent)=>WaitGetScenePresence(agent);
 public static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-00000000000"+n);public static string Hex(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();
 public static void Main(){string line;while((line=Console.ReadLine())!=null){var c=new ClientContext{command=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)))};c.input=new AgentCircuitData{AgentID=Id(1),SessionID=Id(2),circuitcode=123,firstname=c.command.ContainsKey("first")?(c.command["first"].Type==OSDType.Unknown?null:c.T("first")):"First",lastname=c.command.ContainsKey("last")?(c.command["last"].Type==OSDType.Unknown?null:c.T("last")):"Last",teleportFlags=c.command["flags"].AsUInteger()};if(c.command.ContainsKey("region"))c.region=c.command["region"].Type==OSDType.Unknown?null:c.T("region");if(!c.F("missing"))c.manager.AddNewCircuit(123,c.input);c.actor=new(c);var handler=new ClientHarness(c);IPEndPoint endpoint=c.F("null_endpoint")?null:new IPEndPoint(IPAddress.Parse(c.T("ip","127.0.0.1")),1234);string result;bool via=true;try{result=c.T("mode")=="verify"?(handler.Verify(c.F("null_circuit")?null:c.input,endpoint,out via)?"1":"0"):c.T("mode")=="wait"?(handler.Wait(Id(1))!=null?"1":"0"):(handler.CheckClient(Id(1),endpoint)?"1":"0");}catch{result="EX";}var circuit=c.manager.GetAgentCircuitData(Id(1));Console.WriteLine(result+"|"+(via?"1":"0")+"|"+Hex(c.trace)+"|"+c.gets+":"+c.sleeps+":"+c.logouts+":"+c.closes+"|"+(circuit==null?"-":circuit.circuitcode.ToString())+"|"+Hex(c.input.firstname??""));}}
}
public class ClientHarness:ClientReference {public ClientHarness(ClientContext c):base(c){}protected override ScenePresence WaitGetScenePresence(UUID agent){if(!ctx.F("override_wait"))return base.WaitGetScenePresence(agent);ctx.Log("wait-override",agent.ToString());return ctx.F("override_presence",true)?ctx.actor:null;}}
